"use client";

import * as React from "react";
import { cn } from "@/lib/utils";
import "./styles/cstrike.css";

interface ConsoleLine {
  text: string;
  type?: "info" | "warning" | "error" | "system" | "input";
}

interface ConsoleProps extends React.HTMLAttributes<HTMLDivElement> {
  lines: ConsoleLine[];
  onCommand?: (command: string) => void;
  title?: string;
}

const Console = React.forwardRef<HTMLDivElement, ConsoleProps>(
  ({ className, lines, onCommand, title = "Console", ...props }, ref) => {
    const [input, setInput] = React.useState("");
    const scrollRef = React.useRef<HTMLDivElement>(null);

    React.useEffect(() => {
      if (scrollRef.current) {
        scrollRef.current.scrollTop = scrollRef.current.scrollHeight;
      }
    }, [lines]);

    const handleSubmit = (e: React.FormEvent) => {
      e.preventDefault();
      if (input.trim()) {
        onCommand?.(input.trim());
        setInput("");
      }
    };

    const getLineColor = (type?: string) => {
      switch (type) {
        case "error":
          return "text-[var(--cs-hud-red)]";
        case "warning":
          return "text-[var(--cs-hud-amber)]";
        case "system":
          return "text-[var(--cs-accent)]";
        case "input":
          return "text-[var(--cs-text-bright)]";
        default:
          return "text-[var(--cs-text)]";
      }
    };

    return (
      <div
        ref={ref}
        className={cn(
          "w-full max-w-2xl bg-black/90 backdrop-blur-sm",
          "border-2 border-t-[var(--cs-border-light)] border-l-[var(--cs-border-light)]",
          "border-b-[var(--cs-border-dark)] border-r-[var(--cs-border-dark)]",
          className
        )}
        {...props}
      >
        {/* Title bar */}
        <div className="flex items-center justify-between px-3 py-1 bg-[var(--cs-bg-secondary)] border-b border-b-[var(--cs-border-dark)]">
          <span className="cs-font-ui text-xs text-[var(--cs-text-title)]">
            {title}
          </span>
          <span className="cs-font-ui text-xs text-[var(--cs-text-dim)]">~</span>
        </div>

        {/* Output area */}
        <div
          ref={scrollRef}
          className="h-64 overflow-y-auto p-2 font-mono text-xs"
        >
          {lines.map((line, i) => (
            <div key={i} className={cn("leading-relaxed", getLineColor(line.type))}>
              {line.type === "input" && (
                <span className="text-[var(--cs-text-dim)] mr-1">]</span>
              )}
              <span className="cs-font-console">{line.text}</span>
            </div>
          ))}
        </div>

        {/* Input */}
        <form onSubmit={handleSubmit}>
          <div className="flex items-center border-t border-t-[var(--cs-border-dark)] bg-black/50 px-2 py-1">
            <span className="cs-font-console text-xs text-[var(--cs-text-dim)] mr-1">
              ]
            </span>
            <input
              type="text"
              value={input}
              onChange={(e) => setInput(e.target.value)}
              className="flex-1 bg-transparent cs-font-console text-xs text-[var(--cs-text-bright)] outline-none"
              placeholder=""
              spellCheck={false}
              autoComplete="off"
            />
          </div>
        </form>
      </div>
    );
  }
);
Console.displayName = "Console";

export { Console, type ConsoleLine, type ConsoleProps };

/* Counter-Strike 1.6 Design System */

/* CS 1.6 Logo Font - "Counter-Strike" by SoJa (free, public domain) */
@font-face {
  font-family: "Counter-Strike";
  src: url("/fonts/counter-strike.ttf") format("truetype");
  font-weight: 400;
  font-style: normal;
  font-display: swap;
}

/* ===== CS 1.6 VGUI Color System ===== */
:root {
  /* Primary olive-green backgrounds */
  --cs-bg: #4a5942;
  --cs-bg-secondary: #3e4637;
  --cs-bg-dark: #333433;
  --cs-bg-darker: #292929;
  --cs-bg-darkest: #1a1a1a;
  --cs-bg-control: #1a1a1a;
  --cs-bg-selection: #282e22;
  --cs-bg-list: #292929;

  /* Text colors */
  --cs-text: #dedfd6;
  --cs-text-secondary: #a0aa95;
  --cs-text-dim: #75806f;
  --cs-text-disabled: #282e22;
  --cs-text-control: #fffac1;
  --cs-text-bright: #ffc000;
  --cs-text-title: #ffde00;
  --cs-text-menu: #ffcc00;
  --cs-text-menu-hover: #ffffff;
  --cs-text-menu-active: #c0ba50;

  /* Accent colors */
  --cs-accent: #c4b550;
  --cs-accent-secondary: #958831;

  /* Border colors (3D bevel system) */
  --cs-border-light: #8c9284;
  --cs-border-dark: #292c21;
  --cs-border-outline: #000000;

  /* HUD colors (from GoldSrc engine hud.h) */
  --cs-hud-amber: #ffa000;
  --cs-hud-red: #ff1010;
  --cs-hud-green: #00a000;

  /* Team colors */
  --cs-team-ct: #99ccff;
  --cs-team-t: #ff4040;
  --cs-team-neutral: #cccccc;

  /* Slider/scrollbar */
  --cs-slider: #7f8c7f;
  --cs-slider-bg: #1f1f1f;
  --cs-scrollbar-track: #5a6a50;
}

/* ===== Font Classes ===== */
.cs-font-logo {
  font-family: "Counter-Strike", "Impact", sans-serif;
  letter-spacing: 2px;
  text-transform: uppercase;
}

.cs-font-ui {
  font-family: "Verdana", "DejaVu Sans", system-ui, sans-serif;
  font-weight: 600;
  line-height: 1.5;
}

.cs-font-hud {
  font-family: "Courier New", "Courier", monospace;
  font-weight: 700;
  letter-spacing: 1px;
}

.cs-font-console {
  font-family: "Tahoma", "Geneva", sans-serif;
  font-size: 13px;
  line-height: 1.4;
}

/* ===== 3D Beveled Borders ===== */
.cs-bevel-raised {
  border-width: 2px;
  border-style: solid;
  border-top-color: var(--cs-border-light);
  border-left-color: var(--cs-border-light);
  border-bottom-color: var(--cs-border-dark);
  border-right-color: var(--cs-border-dark);
}

.cs-bevel-inset {
  border-width: 2px;
  border-style: solid;
  border-top-color: var(--cs-border-dark);
  border-left-color: var(--cs-border-dark);
  border-bottom-color: var(--cs-border-light);
  border-right-color: var(--cs-border-light);
}

/* ===== HUD Glow Effect ===== */
.cs-hud-glow {
  color: var(--cs-hud-amber);
  text-shadow:
    0 0 8px rgba(255, 160, 0, 0.6),
    0 0 16px rgba(255, 160, 0, 0.3);
}

.cs-hud-glow-red {
  color: var(--cs-hud-red);
  text-shadow:
    0 0 8px rgba(255, 16, 16, 0.6),
    0 0 16px rgba(255, 16, 16, 0.3);
}

.cs-hud-glow-green {
  color: var(--cs-hud-green);
  text-shadow:
    0 0 8px rgba(0, 160, 0, 0.6),
    0 0 16px rgba(0, 160, 0, 0.3);
}

/* ===== Text Shadow (VGUI style) ===== */
.cs-text-shadow {
  text-shadow: 1px 1px 0px rgba(0, 0, 0, 0.8);
}

/* ===== Panel Backgrounds ===== */
.cs-panel {
  background-color: var(--cs-bg);
}

.cs-panel-dark {
  background-color: var(--cs-bg-dark);
}

.cs-panel-control {
  background-color: var(--cs-bg-control);
}
